/// <summary>
/// designed by AVANADE
/// </summary>
class AVAQuickCopyService extends SysOperationServiceBase
{
    QuotationId     copyQuotationId;
}

Method.Source:
/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_contract">AVAQuickCopyContract</param>
public void process(AVAQuickCopyContract _contract)
{
    Set                     /*recordSet,*/ setLineNumbers;
    //SetEnumerator           se;
    RecordSortedList        records;
    boolean                 moreRecs;
    //Common                  record;
    SalesQuotationLine      salesQuotationLine, sqlLVLine;
    SalesQuotationTable     salesQuotationTable;
    KCS_QLLVPosition        lvPos;

    //if (conLen(_contract.parmRecordCon()) > 0)
    if (_contract.parmRecords().len() > 0)
    {
        //recordSet = Set::create(_contract.parmRecordCon());
        records = _contract.parmRecords();
        setLineNumbers  = new Set(Types::Real);
        //se = recordSet.getEnumerator();
        moreRecs = records.first(salesQuotationLine);
        //while (se.moveNext())
        while (moreRecs)
        {
            //record = se.current();

            //if (record.TableId == tableNum(salesQuotationLine))
            //{
                //salesQuotationLine = record;
            salesQuotationTable = salesQuotationLine.salesQuotationTable();
            copyQuotationId     = salesQuotationTable.QuotationId;
            if (!setLineNumbers.in(salesQuotationLine.LineNum))
            {
                lvPos = SalesQuotationLine::KCS_getNewLVPos(salesQuotationLine.QuotationId, salesQuotationLine.KCS_QLLVPosition, true);
                if (!salesQuotationLine.KCS_QLInternalPosition)
                {
                    this.copyCurLine(salesQuotationLine, salesQuotationTable, lvPos);
                }
                else
                {
                    while select sqlLVLine where sqlLVLine.QuotationId == salesQuotationLine.QuotationId
                                                && sqlLVLine.KCS_QLLVPosition == salesQuotationLine.KCS_QLLVPosition
                    {
                        if (!setLineNumbers.in(sqlLVLine.LineNum))
                        {
                            this.copyCurLine(sqlLVLine, salesQuotationTable, lvPos);
                            setLineNumbers.add(sqlLVLine.LineNum);
                        }
                    }
                }
                setLineNumbers.add(salesQuotationLine.LineNum);
            }
            moreRecs = records.next(salesQuotationLine);
            //}
        }

        this.addDuplicateMark();

        SysGlobalCache globalCache = ClassFactory.globalCache();
        globalCache.clear(strFmt("@NDX:NXAP1P2",curUserId(),classStr(SalesQuotationLineType)));
    }
}

/// <summary>
/// designed from AVA
/// </summary>
public void  addDuplicateMark()
{
    SalesQuotationLine          avaSalesQuotationLineLoc;
    SalesQuotationLine          salesQuotationLineItemGrp;    

    while select count(RecId) from salesQuotationLineItemGrp
        group by ItemId
        where salesQuotationLineItemGrp.QuotationId == copyQuotationId
    {
        if (salesQuotationLineItemGrp.RecId > 1)
        {
            ttsbegin;
            update_recordset avaSalesQuotationLineLoc
        setting KCS_MultipleItem = 'X'
        where avaSalesQuotationLineLoc.ItemId == salesQuotationLineItemGrp.itemId
        //&& avaSalesQuotationLineLoc.QuotationId == this.quotationId;
        && avasalesquotationlineloc.QuotationId == copyQuotationId;
            ttscommit;
        }
    }

}

private void copyCurLine(SalesQuotationLine _salesQuotationLine, SalesQuotationTable _salesQuotationTable, KCS_QLLVPosition _lvPos)
{
    SalesQuotationLine      newLine;

    ttsbegin;
    newLine = salesQuotationLine::find(_salesQuotationTable.QuotationId, _salesQuotationTable.maxLineNum() + 1, true);
    newline.initFromSalesQuotationTable(_salesQuotationTable);
    newLine.initFromSalesQuotationLine(_salesQuotationLine, true, true, true);
    newLine.KCS_GAEBExtPosNr = '';
    newLine.KCS_GAEBOZ = '';
    //newLine.LineNum = _salesQuotationTable.maxLineNum() + 1;
    newline.KCS_QLLVPosition = _lvPos;
    newline.KCS_MultipleItem = 'X';
    newline.KCS_QLLVPositionModified();
    newLine.LineNum = newLine.buildLineNumFromLVPos();
    newline.insert();
    //Docu::copy(_salesQuotationLine, newLine);
    Markup::copy(NoYes::No, _salesQuotationLine, newLine);
    ttscommit;
}
